import faqSchema from "@tepian-k3/schema/platform/faq.schema";
import faqQueries from "@tepian-k3/queries/platform/faq.queries";
import auditQueries from "@tepian-k3/queries/platform/audit.queries";
import { z } from "zod";
import { createTRPCRouter, publicProcedure, withPermission } from "../..";
import { runEffect } from "../../utils/run-effect";
import { Effect } from "effect";

export const faqRouter = createTRPCRouter({
  // 1. Get FAQs by Category (Public query)
  getByCategory: publicProcedure
    .input(z.object({ category: z.string() }))
    .query(async ({ input }) => {
      return await runEffect(faqQueries.getFaqsByCategory(input.category));
    }),

  // 2. Get Paginated FAQs (Admin/Staff only)
  getPaginated: withPermission("banners.view")
    .input(faqSchema.getAllFaqsSchema)
    .query(async ({ input }) => {
      const { data, pageCount } = await runEffect(
        faqQueries.getOffsetPaginatedFaqs(input)
      );
      return { data, pageCount };
    }),

  // 3. Create FAQ (Admin only, with audit logging)
  create: withPermission("banners.create")
    .input(faqSchema.createFaqSchema)
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        Effect.gen(function* () {
          const result = yield* faqQueries.createFaq(input);
          
          // Create audit log
          yield* auditQueries.createAuditLog({
            entityType: "faq",
            entityId: result.id,
            action: "create",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: null,
            newValues: result,
            description: `Membuat FAQ baru: "${result.question}" pada kategori "${result.category}"`,
          });

          return result;
        })
      );
    }),

  // 4. Update FAQ (Admin only, with audit logging)
  update: withPermission("banners.update")
    .input(faqSchema.updateFaqSchema)
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        Effect.gen(function* () {
          const oldRecord = yield* faqQueries.getFaqById(input.id);
          const result = yield* faqQueries.updateFaq(input);

          // Create audit log
          yield* auditQueries.createAuditLog({
            entityType: "faq",
            entityId: result.id,
            action: "update",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldRecord || null,
            newValues: result,
            description: `Memperbarui FAQ: "${result.question}"`,
          });

          return result;
        })
      );
    }),

  // 5. Delete FAQ (Admin only, with audit logging)
  delete: withPermission("banners.delete")
    .input(z.object({ id: z.string().uuid() }))
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        Effect.gen(function* () {
          const oldRecord = yield* faqQueries.getFaqById(input.id);
          const result = yield* faqQueries.deleteFaq(input.id);

          // Create audit log
          yield* auditQueries.createAuditLog({
            entityType: "faq",
            entityId: result.id,
            action: "delete",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldRecord || null,
            newValues: result,
            description: `Menghapus FAQ: "${result.question}"`,
          });

          return result;
        })
      );
    }),
});

